u(h\cdot f) = 
u(\lambda^{-1}(\L h)\cdot f) = \lambda^{-1}
u\left(\L(h\cdot(f\circ\sigma))ight) \ &= \lambda^{-1}\L^*
u(h\cdot(f\circ\sigma)) = 
u(h\cdot(f\circ\sigma)) = \mu(f\circ\sigma). \end{align*}

